    return heading('Đơn hàng', 'Theo dõi và xử lý đơn mẫu. Không thu tiền, gửi email hay tạo vận đơn thật.', btn('Tạo đơn hàng', 'new-order', '', 'green')) + `<div class="subnav-tabs" aria-label="Lọc đơn hàng">${[['', 'Tất cả'], ['unfulfilled', 'Chưa xử lý'], ['fulfilled', 'Đã xử lý'], ['pending', 'Chờ thanh toán']].map(([key, name]) => `<button class="subnav-tab ${statusFilter === key ? 'is-active' : ''}" data-order-filter="${key}" aria-pressed="${statusFilter === key}">${name} <b>${data.orders.filter(o => !key || o.payment === key || o.fulfillment === key).length}</b></button>`).join('')}</div><section class="panel management-panel">${toolbar('orders')}<div class="bulk-bar" ${selected.size ? '' : 'hidden'}>${selected.size} đã chọn ${btn('Đánh dấu đã xử lý', 'bulk-fulfill')}</div>${slice.length ? table(['<input type="checkbox" data-select-page aria-label="Chọn cả trang">', 'Mã đơn', 'Khách hàng', 'Ngày tạo', 'Thanh toán', 'Xử lý', 'Tổng cộng'], orderRows(slice)) : empty()}${footer}</section>`;
