    return `<fieldset class="region-settings-card" data-region-card><legend>${esc(item.name || `Khu vực ${index + 1}`)}</legend><div class="region-card-head"><p class="local-note">Khớp theo mã quốc gia ISO từ IP.</p>${btn('Xóa khu vực', 'remove-region', `data-region-id="${esc(item.id)}"`, 'danger')}</div><div class="form-grid">${field('regionId', 'Mã khu vực', item.id, 'required pattern="[a-zA-Z0-9_-]{2,32}"')}${field('regionName', 'Tên hiển thị', item.name, 'required maxlength="80"')}${field('regionCountries', 'Quốc gia (ISO, cách nhau bằng dấu phẩy)', (item.countries || []).join(', '), 'required placeholder="GB, UK"')}${selectField('regionLanguage', 'Ngôn ngữ mặc định', languageOptions(), item.language)}${field('regionLocale', 'Locale định dạng', item.locale, 'required placeholder="en-GB"')}${selectField('regionCurrency', 'Tiền tệ', currencyOptions(), item.currency)}${field('regionExchangeRate', 'Tỷ giá so với tiền tệ gốc', item.exchangeRate, 'type="number" min="0.000001" step="0.000001" required')}${field('regionPriceMultiplier', 'Hệ số giá khu vực', item.priceMultiplier, 'type="number" min="0.000001" step="0.0001" required')}</div><label class="field"><span>Giá riêng theo sản phẩm (JSON, đơn vị nhỏ của tiền tệ)</span><textarea name="regionPriceOverrides" rows="3" placeholder='{"p1": 4999, "p2": 7999}'>${esc(JSON.stringify(item.priceOverrides || {}, null, 2))}</textarea></label><p class="local-note">Nếu có giá riêng, giá đó được ưu tiên. Nếu không, hệ thống dùng giá gốc × tỷ giá × hệ số giá.</p></fieldset>`;
