    return `<form id="localizationSettingsForm"><div class="settings-intro"><p class="panel-kicker">Regional commerce</p><h2>Khu vực, ngôn ngữ &amp; tiền tệ</h2><p class="local-note">Storefront đọc mã quốc gia từ IP edge, chọn khu vực tương ứng rồi áp tiền tệ và bảng giá đã cấu hình. Khách vẫn có thể đổi khu vực thủ công.</p></div><div class="form-grid">${selectField('defaultRegion', 'Khu vực mặc định', (s.regions || []).map(region => [region.id, `${region.name} · ${region.currency}`]), s.defaultRegion)}${selectField('defaultLanguage', 'Ngôn ngữ mặc định', languageOptions(), s.defaultLanguage)}${field('defaultLocale', 'Locale mặc định', s.locale || 'en-US', 'required')}${selectField('defaultCurrency', 'Tiền tệ gốc của catalog', currencyOptions(), s.currency)} </div><div class="setting-row"><div><strong>Tự động chọn theo IP</strong><p>Không tìm thấy quốc gia thì dùng khu vực mặc định.</p></div><label class="toggle"><input type="checkbox" name="autoDetectRegion" ${s.autoDetectRegion !== false ? 'checked' : ''}><span></span></label></div><section class="language-switches"><h3>Ngôn ngữ khả dụng</h3><div class="language-switch-grid">${Object.entries(languages).map(([code, item]) => `<label><input type="checkbox" name="enabledLanguages" value="${esc(code)}" ${item?.enabled !== false ? 'checked' : ''}> <span>${esc(item?.nativeName || item?.name || code)}</span></label>`).join('')}</div></section><div class="region-list-heading"><div><h3>Bảng giá theo khu vực</h3><p class="local-note">Mỗi khu vực có thể dùng tỷ giá, hệ số giá và giá riêng cho từng sản phẩm.</p></div>${btn('+ Thêm khu vực', 'add-region', '', 'green')}</div><div id="regionSettingsList">${(s.regions || []).map((region, index) => regionCardMarkup(region, index)).join('')}</div><p class="form-error" data-localization-error hidden></p><button class="button button--green" type="submit">Lưu cài đặt khu vực</button></form>`;
